mapper.update:
/* PushOutboxMapper.claimSending */

UPDATE TB_NOTI_OUTBOX
   SET SEND_STATUS = 'SENDING'
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND NOTI_ID     = #{notiId}
   AND SEND_STATUS = 'PENDING'

mapper.select:
/* PushOutboxMapper.selectDeviceTokens */
SELECT
      D.DEVICE_UUID  AS deviceUuid
    , D.PUSH_TOKEN   AS pushToken
  FROM TB_USER_DEVICE D
 WHERE D.CMPNY_CD   = #{cmpnyCd}
   AND D.USER_CD    = #{targetUserCd}
   AND D.DEL_YN     = 'N'
   AND D.PUSH_TOKEN IS NOT NULL

mapper.update:
/* PushOutboxMapper.markSent */

UPDATE TB_NOTI_OUTBOX
   SET SEND_STATUS = 'SENT'
     , SENT_DATE   = NOW()
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND NOTI_ID     = #{notiId}
   AND SEND_STATUS IN ('SENDING', 'PENDING')

/* PushOutboxMapper.markFailed */

UPDATE TB_NOTI_OUTBOX
   SET SEND_STATUS = 'FAILED'
     , RETRY_CNT   = #{retryCnt}
     , ERROR_MSG   = #{errorMsg}
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND NOTI_ID     = #{notiId}
   AND SEND_STATUS IN ('SENDING', 'PENDING')

/* PushOutboxMapper.incrementRetryAndRevertPending */

UPDATE TB_NOTI_OUTBOX
   SET SEND_STATUS = 'PENDING'
     , RETRY_CNT   = RETRY_CNT + 1
     , ERROR_MSG   = #{errorMsg}
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND NOTI_ID     = #{notiId}
   AND SEND_STATUS = 'SENDING'

/* PushOutboxMapper.softDeleteDeviceToken */

UPDATE TB_USER_DEVICE
   SET DEL_YN      = 'Y'
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND DEVICE_UUID = #{deviceUuid}
   AND DEL_YN      = 'N'

mapper.select:
/* PushOutboxMapper.isSuppressed */
SELECT EXISTS(
    SELECT 1
      FROM TB_USER_PUSH_SETTING
     WHERE CMPNY_CD  = #{cmpnyCd}
       AND USER_CD   = #{targetUserCd}
       AND NOTI_TYPE IN (#{notiType}, '__MASTER__')
       AND USE_YN    = 'N'
)

mapper.update:
/* PushOutboxMapper.markSuppressed */

UPDATE TB_NOTI_OUTBOX
   SET SEND_STATUS = 'SUPPRESSED'
     , SENT_DATE   = NOW()
     , ERROR_MSG   = #{errorMsg}
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND NOTI_ID     = #{notiId}
   AND SEND_STATUS = 'SENDING'
